/* From Uiverse.io by ammarsaa - Source: https://uiverse.io/Yaya12085/short-turtle-53 AND https://uiverse.io/micaelgomestavares/purple-cow-92 - Tags: simple, blue, black, form, dark, sign-up */
.__UIV_SCOPE__ .form {
  display: flex;
  flex-direction: column;
  gap: 10px;
  max-width: 350px;
  padding: 20px;
  border-radius: 20px;
  position: relative;
  background-color: #1a1a1a;
  color: #fff;
  border: 1px solid #333;
}

.__UIV_SCOPE__ .title {
  font-size: 28px;
  font-weight: 600;
  letter-spacing: -1px;
  position: relative;
  display: flex;
  align-items: center;
  padding-left: 30px;
  color: #00bfff;
}

.__UIV_SCOPE__ .title::before {
  width: 18px;
  height: 18px;
}

.__UIV_SCOPE__ .title::after {
  width: 18px;
  height: 18px;
  animation: pulse 1s linear infinite;
}

.__UIV_SCOPE__ .title::before,
.__UIV_SCOPE__ .title::after {
  position: absolute;
  content: "";
  height: 16px;
  width: 16px;
  border-radius: 50%;
  left: 0px;
  background-color: #00bfff;
}

.__UIV_SCOPE__ .message, 
.__UIV_SCOPE__ .signin {
  font-size: 14.5px;
  color: rgba(255, 255, 255, 0.7);
}

.__UIV_SCOPE__ .signin {
  text-align: center;
}

.__UIV_SCOPE__ .signin a:hover {
  text-decoration: underline royalblue;
}

.__UIV_SCOPE__ .signin a {
  color: #00bfff;
}

.__UIV_SCOPE__ .flex {
  display: flex;
  width: 100%;
  gap: 6px;
}

.__UIV_SCOPE__ .form label {
  position: relative;
}

.__UIV_SCOPE__ .form label .input {
  background-color: #333;
  color: #fff;
  width: 100%;
  padding: 20px 05px 05px 10px;
  outline: 0;
  border: 1px solid rgba(105, 105, 105, 0.397);
  border-radius: 10px;
}

.__UIV_SCOPE__ .form label .input + span {
  color: rgba(255, 255, 255, 0.5);
  position: absolute;
  left: 10px;
  top: 0px;
  font-size: 0.9em;
  cursor: text;
  transition: 0.3s ease;
}

.__UIV_SCOPE__ .form label .input:placeholder-shown + span {
  top: 12.5px;
  font-size: 0.9em;
}

.__UIV_SCOPE__ .form label .input:focus + span,
.__UIV_SCOPE__ .form label .input:valid + span {
  color: #00bfff;
  top: 0px;
  font-size: 0.7em;
  font-weight: 600;
}

.__UIV_SCOPE__ .input {
  font-size: medium;
}

.__UIV_SCOPE__ .submit {
  border: none;
  outline: none;
  padding: 10px;
  border-radius: 10px;
  color: #fff;
  font-size: 16px;
  transform: .3s ease;
  background-color: #00bfff;
}

.__UIV_SCOPE__ .submit:hover {
  background-color: #00bfff96;
}

@keyframes pulse {
  from {
    transform: scale(0.9);
    opacity: 1;
  }

  to {
    transform: scale(1.8);
    opacity: 0;
  }
}
